            _ = &sp;
            const input_path = sp.path;
            const input = ((inputs.object.get(input_path)) orelse continue);
            if ((input != .object)) {
                continue;
            }
            _ = try writer.print("### `{s}`\n\n", .{ input_path });
            if (bytes_in_output.get(input_path)) |contrib| {
                _ = &contrib;
                if ((contrib > 0)) {
                    _ = try writer.print("- **Output contribution**: {f}\n", .{ bun.fmt.size(contrib, .{}) });
                }
            }
            if (input.object.get("format")) |format| {
                _ = &format;
                if ((format == .@"string")) {
                    _ = try writer.print("- **Format**: {s}\n", .{ format.string });
                }
            }
            if (imported_by.get(input_path)) |importers| {
                _ = &importers;
                _ = try writer.print("- **Imported by** ({d} files):", .{ importers.items.len });
                if ((importers.items.len <= 5)) {
                    for (importers.items) |importer| {
                        _ = &importer;
                        _ = try writer.print(" `{s}`", .{ importer });
                    }
                } else {
                    for (cp_iter_slice(importers.items[0..5])) |importer| {
                        _ = &importer;
                        _ = try writer.print(" `{s}`", .{ importer });
                    }
                    _ = try writer.print(" +{d} more", .{ (importers.items.len - 5) });
                }
                _ = try writer.writeAll("\n");
            } else {
                _ = try writer.writeAll("- **Imported by**: (entry point || orphan)\n");
            }
            if (input.object.get("imports")) |imps| {
                _ = &imps;
                if (((imps == .array) and (imps.array.items.len > 0))) {
                    _ = try writer.writeAll("- **Imports**:\n");
                    for (imps.array.items) |imp| {
                        _ = &imp;
                        if ((imp == .object)) {
                            const target_res = importTarget(imp.object);
                            const path = ((target_res.path) orelse continue);
                            const kind = ((imp.object.get("kind")) orelse continue);
                            if (((path != .@"string") or (kind != .@"string"))) {
                                continue;
                            }
                            const is_external = target_res.is_external;
                            const original = blk: {
                            if (imp.object.get("original")) |orig| {
                                _ = &orig;
                                if ((orig == .@"string")) {
                                    break :blk orig.string;
                                }
                            }
                            break :blk null;
};
                            const imported_contrib: ?u64 = (if ((!is_external)) bytes_in_output.get(path.string) else null);
                            if (is_external) {
                                if (original) |orig| {
                                    _ = &orig;
                                    _ = try writer.print("  - `{s}` ({s}, **external**, specifier: `{s}`)\n", .{ path.string, kind.string, orig });
                                } else {
                                    _ = try writer.print("  - `{s}` ({s}, **external**)\n", .{ path.string, kind.string });
                                }
                            } else {
                                if (imported_contrib) |contrib| {
                                    _ = &contrib;
                                    if ((contrib > 0)) {
                                        if (original) |orig| {
                                            _ = &orig;
                                            _ = try writer.print("  - `{s}` ({s}, contributes {f}, specifier: `{s}`)\n", .{ path.string, kind.string, bun.fmt.size(contrib, .{}), orig });
                                        } else {
                                            _ = try writer.print("  - `{s}` ({s}, contributes {f})\n", .{ path.string, kind.string, bun.fmt.size(contrib, .{}) });
                                        }
                                    } else {
                                        if (original) |orig| {
                                            _ = &orig;
                                            _ = try writer.print("  - `{s}` ({s}, specifier: `{s}`)\n", .{ path.string, kind.string, orig });
                                        } else {
                                            _ = try writer.print("  - `{s}` ({s})\n", .{ path.string, kind.string });
                                        }
                                    }
                                } else {
                                    if (original) |orig| {
                                        _ = &orig;
                                        _ = try writer.print("  - `{s}` ({s}, specifier: `{s}`)\n", .{ path.string, kind.string, orig });
                                    } else {
                                        _ = try writer.print("  - `{s}` ({s})\n", .{ path.string, kind.string });
                                    }
                                }
                            }
                            if (imp.object.get("with")) |with| {
                                _ = &with;
                                if ((with == .object)) {
                                    if (with.object.get("type")) |type_val| {
                                        _ = &type_val;
                                        if ((type_val == .@"string")) {
                                            _ = try writer.print("    - with type: `{s}`\n", .{ type_val.string });
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
            _ = try writer.writeAll("\n");
        }
        _ = try writer.writeAll("## Raw Data for Searching\n\n");
        _ = try writer.writeAll("This section contains raw, grep-friendly data. Use these patterns:\n");
        _ = try writer.writeAll("- `[MODULE:` - Find all modules\n");
        _ = try writer.writeAll("- `[OUTPUT_BYTES:` - Find output contribution for each module\n");
        _ = try writer.writeAll("- `[IMPORT:` - Find all import relationships\n");
        _ = try writer.writeAll("- `[IMPORTED_BY:` - Find reverse dependencies\n");
        _ = try writer.writeAll("- `[ENTRY:` - Find entry points\n");
        _ = try writer.writeAll("- `[EXTERNAL:` - Find external imports\n");
        _ = try writer.writeAll("- `[NODE_MODULES:` - Find node_modules files\n\n");
        _ = try writer.writeAll("### All Modules\n\n");
        _ = try writer.writeAll("```\n");
        for (input_files.items) |info| {
            _ = &info;
            _ = try writer.print("[MODULE: {s}]\n", .{ info.path });
            if ((info.bytes_in_output > 0)) {
                _ = try writer.print("[OUTPUT_BYTES: {s} = {d} bytes]\n", .{ info.path, info.bytes_in_output });
            }
            if ((info.format.len > 0)) {
                _ = try writer.print("[FORMAT: {s} = {s}]\n", .{ info.path, info.format });
            }
            if (info.is_node_modules) {
                _ = try writer.print("[NODE_MODULES: {s}]\n", .{ info.path });
            }
        }
        _ = try writer.writeAll("```\n\n");
        _ = try writer.writeAll("### All Imports\n\n");
        _ = try writer.writeAll("```\n");
        var import_iter2 = inputs.object.iterator();
        _ = &import_iter2;
        while (import_iter2.next()) |entry| {
            const source_path = entry.key_ptr.*;
            const input2 = entry.value_ptr.*;
            if ((input2 != .object)) {
                continue;
            }
            if (input2.object.get("imports")) |imps| {
                _ = &imps;
                if ((imps == .array)) {
                    for (imps.array.items) |imp| {
                        _ = &imp;
                        if ((imp == .object)) {
                            const target_res = importTarget(imp.object);
                            const is_ext = target_res.is_external;
                            if (target_res.path) |imp_path| {
                                _ = &imp_path;
                                if ((imp_path == .@"string")) {
                                    if (is_ext) {
                                        _ = try writer.print("[EXTERNAL: {s} imports {s}]\n", .{ source_path, imp_path.string });
                                    } else {
                                        _ = try writer.print("[IMPORT: {s} -> {s}]\n", .{ source_path, imp_path.string });
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
        _ = try writer.writeAll("```\n\n");
        _ = try writer.writeAll("### Reverse Dependencies (Imported By)\n\n");
        _ = try writer.writeAll("```\n");
        var ib_iter2 = imported_by.iterator();
        _ = &ib_iter2;
        while (ib_iter2.next()) |entry| {
            const target = entry.key_ptr.*;
            for (entry.value_ptr.items) |importer| {
                _ = &importer;
                _ = try writer.print("[IMPORTED_BY: {s} <- {s}]\n", .{ target, importer });
            }
        }
        _ = try writer.writeAll("```\n\n");
        _ = try writer.writeAll("### Entry Points\n\n");
        _ = try writer.writeAll("```\n");
        var out_iter3 = outputs.object.iterator();
        _ = &out_iter3;
        while (out_iter3.next()) |entry| {
            const output_path2 = entry.key_ptr.*;
            const output2 = entry.value_ptr.*;
            if ((output2 != .object)) {
                continue;
            }
            if (output2.object.get("entryPoint")) |ep| {
                _ = &ep;
                if ((ep == .@"string")) {
                    var size: u64 = 0;
                    _ = &size;
                    if (output2.object.get("bytes")) |bytes| {
                        _ = &bytes;
                        if ((bytes == .integer)) {
                            size = @as(u64, @intCast(bytes.integer));
                        }
                    }
                    _ = try writer.print("[ENTRY: {s} -> {s} ({d} bytes)]\n", .{ ep.string, output_path2, size });
                }
            }
        }
        _ = try writer.writeAll("```\n\n");
        if ((node_modules_count > 0)) {
            _ = try writer.writeAll("### node_modules Summary\n\n");
            _ = try writer.writeAll("```\n");
            for (input_files.items) |info| {
                _ = &info;
                if ((info.is_node_modules and (info.bytes_in_output > 0))) {
                    _ = try writer.print("[NODE_MODULES: {s} (contributes {d} bytes)]\n", .{ info.path, info.bytes_in_output });
                }
            }
            _ = try writer.writeAll("```\n");
        }
        _ = _guard_md.disarm();
        return md.toOwnedSlice();
}

pub fn stripParentRefs(path: []const u8) []const u8 {
        var result = path;
        _ = &result;
        while (((result.len >= 3) and std.mem.startsWith(u8, result, "../"))) {
            result = result[3..];
        }
        while (((result.len >= 2) and std.mem.startsWith(u8, result, "./"))) {
            result = result[2..];
        }
        return result;
}
